// Some portions generated by Co-Pilot
"use client";

import { useId } from "react";
import { useTranslations } from "next-intl";
import { FiChevronDown } from "react-icons/fi";
import { packageTypes } from "@/utils/defaults";

interface Option {
  name: string;
  value: string;
}

interface ReleaseSelectorProps {
  marketplace?: boolean;
  versions: Option[];
  osOptions: Option[];
  architectureOptions: Option[];
  defaultVersion?: string;
  defaultOS?: string;
  defaultArch?: string;
  defaultPackageType?: string;
  updateVersion: (version: string) => void;
  updateOS: (os: string) => void;
  updateArch: (arch: string) => void;
  updatePackageType?: (type: string) => void;
}

const osToArchitectures: Record<string, string[]> = {
  windows: ["x64", "x86", "aarch64"],
  mac: ["x64", "aarch64"],
  linux: ["x64", "x86", "arm", "aarch64", "ppc64le", "s390x", "riscv64"],
  alpine_linux: ["x64", "aarch64"],
  aix: ["ppc64"],
  solaris: ["sparcv9", "x64"],
};

const ReleaseSelector = ({
  marketplace,
  versions,
  osOptions,
  architectureOptions,
  defaultVersion,
  defaultOS = "any",
  defaultArch = "any",
  defaultPackageType = "any",
  updateVersion,
  updateOS,
  updateArch,
  updatePackageType,
}: ReleaseSelectorProps) => {
  const t = useTranslations("Temurin.Releases.ReleaseFilters");
  const id = useId();
  const filteredOS = osOptions.filter(
    (os) =>
      defaultArch === "any" ||
      osToArchitectures[os.value]?.includes(defaultArch),
  );
  const filteredArchitectures = architectureOptions.filter(
    (arch) =>
      defaultOS === "any" || osToArchitectures[defaultOS]?.includes(arch.value),
  );
  const versionOptions =
    defaultVersion &&
    !versions.some((version) => version.value === defaultVersion)
      ? [{ name: defaultVersion, value: defaultVersion }, ...versions]
      : versions;
  const fields = [
    {
      key: "os",
      label: t("operating-system"),
      value: defaultOS,
      options: [{ name: t("any-os"), value: "any" }, ...filteredOS],
      update: (os: string) => {
        updateOS(os);
        if (
          os !== "any" &&
          defaultArch !== "any" &&
          !osToArchitectures[os]?.includes(defaultArch)
        )
          updateArch("any");
      },
    },
    {
      key: "arch",
      label: t("architecture"),
      value: defaultArch,
      options: [
        { name: t("any-architecture"), value: "any" },
        ...filteredArchitectures.map((arch) => ({
          ...arch,
          name:
            defaultOS === "mac"
              ? arch.value === "aarch64"
                ? "Apple Silicon (aarch64)"
                : arch.value === "x64"
                  ? "Intel (x64)"
                  : arch.name
              : arch.name,
        })),
      ],
      update: (arch: string) => {
        updateArch(arch);
        if (
          arch !== "any" &&
          defaultOS !== "any" &&
          !osToArchitectures[defaultOS]?.includes(arch)
        )
          updateOS("any");
      },
    },
    {
      key: "version",
      label: t("version"),
      value: defaultVersion ?? versions[0]?.value ?? "",
      options: versionOptions,
      update: updateVersion,
    },
    ...(marketplace
      ? [
          {
            key: "package",
            label: t("package-type"),
            value: defaultPackageType,
            options: [
              { name: t("any-package-type"), value: "any" },
              ...packageTypes,
            ],
            update: (type: string) => updatePackageType?.(type),
          },
        ]
      : []),
  ];

  return (
    <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
      {fields.map((field) => (
        <div key={field.key}>
          <label
            htmlFor={`${id}-${field.key}`}
            className="mb-2 block text-xs font-medium text-grey"
          >
            {field.label}
          </label>
          <div className="relative">
            <select
              id={`${id}-${field.key}`}
              data-testid={`marketplace-${field.key}-selector`}
              value={field.value}
              onChange={(event) => field.update(event.target.value)}
              className="min-h-12 w-full min-w-0 appearance-none rounded-xl border border-white/15 bg-[#1c1040] py-3 pl-3 pr-9 text-sm text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink"
            >
              {field.options.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.name}
                </option>
              ))}
            </select>
            <FiChevronDown
              className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-grey"
              aria-hidden="true"
            />
          </div>
        </div>
      ))}
    </div>
  );
};

export default ReleaseSelector;
